@dataclass
class GeoBounds:
    """Geographic bounds in lat/lon."""
    lat_min: float
    lat_max: float
    lon_min: float
    lon_max: float
    
    @property
    def lat_center(self):
        return (self.lat_min + self.lat_max) / 2
    
    @property
    def lon_center(self):
        return (self.lon_min + self.lon_max) / 2
    
    @property
    def lat_span(self):
        return self.lat_max - self.lat_min
    
    @property
    def lon_span(self):
        return self.lon_max - self.lon_min

# %% ../nbs/03_terrain.ipynb #d445eba7
EARTH_RADIUS_M = 6_371_000  # meters

@patch
def meters_per_degree_lon(self: GeoBounds, lat: float) -> float:
    """Meters per degree longitude at given latitude."""
    return EARTH_RADIUS_M * radians(1) * cos(radians(lat))

@patch
def meters_per_degree_lat(self: GeoBounds) -> float:
    """Meters per degree latitude (nearly constant)."""
    return EARTH_RADIUS_M * radians(1)

@patch
def haversine_distance(self: GeoBounds, lat1: float, lon1: float, 
                       lat2: float, lon2: float) -> float:
    """Great-circle distance in meters between two points."""
    φ1, φ2 = radians(lat1), radians(lat2)
    Δφ = radians(lat2 - lat1)
    Δλ = radians(lon2 - lon1)
    
    a = sin(Δφ/2)**2 + cos(φ1) * cos(φ2) * sin(Δλ/2)**2
    return EARTH_RADIUS_M * 2 * atan2(sqrt(a), sqrt(1-a))

@patch
def pixel_to_latlon(self: GeoBounds, px: float, py: float, 
                    width: float, height: float) -> tuple[float, float]:
    """Convert pixel coords to lat/lon with latitude correction."""
    # Normalize to 0-1
    nx = px / width
    ny = py / height
    
    # Linear in latitude (y maps to lat, inverted since y grows down)
    lat = self.lat_max - ny * self.lat_span
    
    # Longitude adjusted for latitude - use center latitude for now
    # More sophisticated: could interpolate based on current row
    lon = self.lon_min + nx * self.lon_span
    
    return lat, lon

@patch  
def latlon_to_pixel(self: GeoBounds, lat: float, lon: float,
                    width: float, height: float) -> tuple[float, float]:
    """Convert lat/lon to pixel coords."""
    ny = (self.lat_max - lat) / self.lat_span
    nx = (lon - self.lon_min) / self.lon_span
    return nx * width, ny * height

@patch
def area_at_latitude(self: GeoBounds, lat: float, hex_radius_m: float) -> float:
    """Hex area in square meters at given latitude."""
    # Hex area = (3√3/2) * r²
    return (3 * sqrt(3) / 2) * hex_radius_m**2


