@dataclass
class USGSTerrainFetcher:
    """Build terrain from USGS EPQS elevation data."""
    
    EPQS_URL = "https://epqs.nationalmap.gov/v1/json"
    
    async def fetch_elevation(self, client: httpx.AsyncClient, lat: float, lon: float) -> float | None:
        """Fetch single elevation point from USGS EPQS."""
        try:
            resp = await client.get(self.EPQS_URL, params={
                'x': lon, 'y': lat,  # Note: x=lon, y=lat
                'units': 'Meters',
                'wkid': 4326,
                'includeDate': 'False'
            }, timeout=10)
            data = resp.json()
            return data.get('value')
        except Exception as e:
            print(f"Error fetching ({lat}, {lon}): {e}")
            return None
    
    async def fetch_batch(self, points: list[tuple[float, float]], 
                          max_concurrent: int = 10) -> list[float | None]:
        """Fetch elevations for multiple points with rate limiting."""
        semaphore = asyncio.Semaphore(max_concurrent)
        
        async def bounded_fetch(client, lat, lon):
            async with semaphore:
                return await self.fetch_elevation(client, lat, lon)
        
        async with httpx.AsyncClient() as client:
            tasks = [bounded_fetch(client, lat, lon) for lat, lon in points]
            return await asyncio.gather(*tasks)
    
    


