@patch
async def build_terrain(self: USGSTerrainFetcher, geo: GeoBounds, approx_hexes: int = 500,
                        radius: float = 25.0) -> Terrain:
    """Build terrain with latitude-corrected sampling for equal ground coverage."""
    lat_span = geo.lat_span
    lon_span = geo.lon_span
    
    # Use center latitude for initial grid sizing
    center_lat = geo.lat_center
    lon_scale = cos(radians(center_lat))
    
    # Aspect ratio in "real" distances
    aspect = (lon_span * lon_scale) / lat_span
    
    nrows = int(math.sqrt(approx_hexes / aspect))
    ncols = int(nrows * aspect)
    nrows = max(nrows, 2)
    ncols = max(ncols, 2)
    
    width = ncols * radius * 1.5 + radius
    height = nrows * radius * math.sqrt(3) + radius
    bounds = MapRect(MapCord(0, 0), MapSize(width, height))
    
    terrain = Terrain(bounds, radius=radius)
    terrain.geo = geo
    terrain.elevations = np.zeros(len(terrain.hexGrid.hexes))
    
    # Store lat/lon per hex for later use (weather, etc)
    terrain.fields['latitude'] = np.zeros(len(terrain.hexGrid.hexes))
    terrain.fields['longitude'] = np.zeros(len(terrain.hexGrid.hexes))
    
    grid = terrain.hexGrid
    
    points = []
    for idx in range(len(grid.hexes)):
        row = idx // grid.nCols
        col = idx % grid.nCols
        
        # Latitude is linear (rows map evenly to lat)
        lat = geo.lat_max - (row / max(grid.nRows - 1, 1)) * lat_span
        
        # Longitude step adjusted for this row's latitude
        # At higher latitudes, same pixel distance = more degrees longitude
        row_lon_scale = cos(radians(lat))
        if row_lon_scale < 0.1:  # Near poles, clamp to avoid division issues
            row_lon_scale = 0.1
        
        # Effective lon span for this row (in degrees that cover same ground distance)
        effective_lon_span = lon_span * (lon_scale / row_lon_scale)
        lon_offset = (effective_lon_span - lon_span) / 2  # Center the adjusted span
        
        lon = (geo.lon_min - lon_offset) + (col / max(grid.nCols - 1, 1)) * effective_lon_span
        
        points.append((lat, lon))
        terrain.fields['latitude'][idx] = lat
        terrain.fields['longitude'][idx] = lon
    
    elevations = await self.fetch_batch(points)
    
    for idx, elev in enumerate(elevations):
        terrain.elevations[idx] = elev if elev is not None else 0.0
    
    return terrain

